document.addEventListener('DOMContentLoaded', () => {
  // 現在のURLのパスを取得（末尾のスラッシュの有無による判定ブレを防ぐ）
  const currentPath = window.location.pathname.replace(/\/$/, '');

  // 洗濯機クリーニングメニュー内のカードを取得
  const categoryCards = document.querySelectorAll('.p-cleaning-menu__contents .c-category-card');

  categoryCards.forEach(card => {
    // リンク先のパスを取得
    const linkPath = card.pathname.replace(/\/$/, '');

    // 現在のページとリンク先が同じ場合
    if (currentPath === linkPath) {
      card.classList.add('is-current-page'); // CSS用のクラスを付与
      card.removeAttribute('href');          // href属性を削除してリンクとして機能させない
    }
  });
});